// UI strings. Keys are the Korean source text (same as the macOS catalog); tables are generated by
// tools/gen-i18n.mjs. t(key, ...args) fills {0}, {1}… and picks plural forms with Intl.PluralRules.
import ko from "./ko.json";
import en from "./en.json";
import ja from "./ja.json";
import zhHans from "./zh-Hans.json";
import type { MsgKey } from "./keys";

export type { MsgKey } from "./keys";
export type Lang = "ko" | "en" | "ja" | "zh-Hans";
export type Arg = string | number;

type Entry = string | Record<string, string>;
type Table = Record<string, Entry>;

const TABLES: Record<Lang, Table> = { ko, en, ja, "zh-Hans": zhHans } as Record<Lang, Table>;

let lang: Lang = "en";
let pluralRules = new Intl.PluralRules("en");
let numberFormat = new Intl.NumberFormat("en");

/** ko* → ko, ja* → ja, zh* → zh-Hans, anything else → en (same rule as the macOS app). */
export function langFromLocale(locale: string | undefined | null): Lang {
  const l = (locale ?? "").toLowerCase();
  if (l.startsWith("ko")) return "ko";
  if (l.startsWith("ja")) return "ja";
  if (l.startsWith("zh")) return "zh-Hans";
  return "en";
}

export function setLanguage(locale: string): Lang {
  lang = langFromLocale(locale);
  pluralRules = new Intl.PluralRules(lang);
  numberFormat = new Intl.NumberFormat(lang);
  if (typeof document !== "undefined") document.documentElement.lang = lang;
  return lang;
}

export function currentLang(): Lang {
  return lang;
}

/** BCP-47 tag for Intl formatters. */
export function intlLocale(): string {
  return lang;
}

export function formatNumber(n: number): string {
  return numberFormat.format(n);
}

function fmtArg(a: Arg | undefined): string {
  if (a === undefined) return "";
  return typeof a === "number" ? formatNumber(a) : a;
}

/** Fills `{n}` and `{n, plural, one {…} other {…}}` (with `#` = the number). */
function fill(template: string, args: Arg[]): string {
  let out = "";
  let i = 0;
  while (i < template.length) {
    const ch = template[i];
    if (ch === "{") {
      const rest = template.slice(i);
      const simple = /^\{(\d+)\}/.exec(rest);
      if (simple) {
        out += fmtArg(args[Number(simple[1])]);
        i += simple[0].length;
        continue;
      }
      const plural = /^\{(\d+),\s*plural,\s*/.exec(rest);
      if (plural) {
        let j = i + plural[0].length;
        const branches: Record<string, string> = {};
        while (j < template.length) {
          while (template[j] === " ") j++;
          if (template[j] === "}") break;
          const sel = /^(=\d+|zero|one|two|few|many|other)\s*\{/.exec(template.slice(j));
          if (!sel) break;
          j += sel[0].length;
          let depth = 1;
          let k = j;
          while (k < template.length && depth > 0) {
            if (template[k] === "{") depth++;
            else if (template[k] === "}") depth--;
            k++;
          }
          branches[sel[1]] = template.slice(j, k - 1);
          j = k;
        }
        const n = Number(args[Number(plural[1])] ?? 0);
        const branch = branches[`=${n}`] ?? branches[pluralRules.select(n)] ?? branches.other ?? "";
        out += fill(branch.replace(/#/g, formatNumber(n)), args);
        i = j + 1;
        continue;
      }
    }
    out += ch;
    i++;
  }
  return out;
}

function lookup(key: string, args: Arg[]): string {
  const entry: Entry | undefined = TABLES[lang][key] ?? TABLES.ko[key];
  if (entry === undefined) return fill(key, args);
  if (typeof entry === "string") return fill(entry, args);
  const n = args.find((a): a is number => typeof a === "number") ?? 0;
  const template = entry[pluralRules.select(n)] ?? entry.other ?? Object.values(entry)[0] ?? key;
  return fill(template, args);
}

/** Translates a known key. Unknown keys are a type error; at run time a missing key shows the key. */
export function t(key: MsgKey, ...args: Arg[]): string {
  return lookup(key, args);
}

/** For keys that arrive at run time (e.g. leftover `reason` from the backend). */
export function tDynamic(key: string, ...args: Arg[]): string {
  return lookup(key, args);
}

/** Splits a translated string on **bold** markers: even indexes are plain, odd are bold. */
export function boldParts(text: string): string[] {
  return text.split("**");
}
